<script lang="ts">import {gameCommands,gameState} from '$lib/application/game-store';import {AREAS,MINERALS,type AreaId} from '$lib/content/exploration';export let close:()=>void;const areas=Object.entries(AREAS) as Array<[AreaId,(typeof AREAS)[AreaId]]>;</script>
<div class="modal" role="dialog" aria-modal="true"><section><button class="close" on:click={close}>×</button><small>PETA NUSANTARA</small><h2>{AREAS[$gameState.exploration.currentArea].name}</h2><p>{AREAS[$gameState.exploration.currentArea].description}</p><div class="areas">{#each areas as [id,area]}<article class:locked={!$gameState.exploration.unlocked.includes(id)}><b>{area.name}</b><span>{area.description}</span>{#if $gameState.exploration.unlocked.includes(id)}<button disabled={$gameState.exploration.currentArea===id} on:click={()=>gameCommands.travel(id)}>Pergi</button>{:else}<button on:click={()=>gameCommands.unlockArea(id)}>Buka · {area.unlockCost} koin</button>{/if}</article>{/each}</div>
{#if $gameState.exploration.currentArea==='mine'}<div class="mine"><h3>TAMBANG · PICKAXE LV.{$gameState.mining.pickaxe}</h3><button on:click={()=>gameCommands.upgradePickaxe()}>Upgrade Pickaxe · {$gameState.mining.pickaxe*300} koin</button><div class="nodes">{#each $gameState.mining.nodes as node}<button disabled={node.depleted} style={`--ore:${MINERALS[node.mineral].color}`} on:click={()=>gameCommands.mine(node.id)}><i></i><b>{MINERALS[node.mineral].name}</b><span>{node.depleted?'Habis':`${node.hits}/${MINERALS[node.mineral].hardness}`}</span></button>{/each}</div></div>{/if}</section></div>
<style>.modal{position:fixed;z-index:20;inset:0;background:#071a16dd;display:grid;place-items:center;padding:15px}section{position:relative;width:min(800px,100%);max-height:92vh;overflow:auto;padding:25px;background:#e8ddb8;color:#203c35;border:8px double #6e5037}.close{position:absolute;right:8px;top:6px;border:0;background:none;font-size:1.6rem}h2{font:900 2rem Georgia;margin:.2rem 0}.areas{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.areas article{display:grid;gap:7px;padding:11px;background:#fff7d9;border:2px solid #927340}.areas article.locked{background:#c7bea3}.areas span{font-size:.7rem}.areas button,.mine>button{padding:7px;background:#315d4b;color:white;border:0}.nodes{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-top:12px}.nodes button{display:grid;place-items:center;padding:10px;background:#3c3d3b;color:white;border:2px solid #171918}.nodes i{width:25px;height:20px;background:var(--ore);clip-path:polygon(20% 0,80% 8%,100% 70%,60% 100%,0 70%)}.nodes span{font-size:.65rem}@media(max-width:600px){.areas{grid-template-columns:repeat(2,1fr)}.nodes{grid-template-columns:repeat(2,1fr)}}</style>
